          <template v-else-if="view==='wanted'"><button :class="['tab-button',{selected:!onlyMine}]" @click="onlyMine=false">全部求购</button><button :class="['tab-button',{selected:onlyMine}]" @click="onlyMine=true">我的求购</button><select v-model="statusFilter" aria-label="求购状态"><option value="">全部状态</option><option v-for="status in wantStatuses" :key="status" :value="status">{{statusText(status)}}</option></select></template>
          <template v-else-if="view==='orders'"><button v-for="status in ['','PENDING','CONFIRMED','COMPLETED','CANCELLED']" :key="status" :class="['tab-button',{selected:statusFilter===status}]" @click="statusFilter=status">{{status?statusText(status):'全部订单'}}</button></template>
          <template v-else-if="view==='messages'"><button v-for="status in ['','PENDING','REPLIED']" :key="status" :class="['tab-button',{selected:statusFilter===status}]" @click="statusFilter=status">{{status==='PENDING'?'待回复':status==='REPLIED'?'已回复':'全部咨询'}}</button></template><button class="text-action reset-filters" @click="resetFilters">重置筛选</button>
        </div>
