        <div v-else-if="!filteredItems.length" class="empty"><el-icon><Search/></el-icon><h3>这里暂时没有记录</h3><p>{{emptyText}}</p><button class="button secondary" @click="resetFilters">清除筛选</button></div>
        <div v-else-if="['market','mine','favorites'].includes(view)" class="goods-grid">
