        <div v-else-if="view==='wanted'" class="wanted-grid"><article v-for="want in pagedItems" :key="want.id" class="want-card"><div class="want-card-top"><span class="category-chip">{{want.category}}</span><el-tag :type="tagType(want.status)">{{statusText(want.status)}}</el-tag></div><h3>{{want.title}}</h3><p>{{want.description}}</p><div class="want-budget"><span>期望预算</span><b>{{want.budget>0?'¥'+money(want.budget):'面议'}}</b></div><div class="seller"><span class="mini-avatar">{{want.requesterName?.slice(0,1)}}</span><span>{{want.requesterName}}</span><small>{{formatDate(want.createdAt)}}</small></div><div v-if="want.userId===currentUser?.id&&['PENDING','PUBLISHED'].includes(want.status)" class="manage-actions"><button class="button secondary compact" @click="openWant(want)"><el-icon><Edit/></el-icon>编辑</button><button v-if="want.status==='PUBLISHED'" class="button secondary compact" :disabled="saving" @click="changeWantStatus(want,'FOUND')">已找到</button><button class="text-action danger" :disabled="saving" @click="changeWantStatus(want,'WITHDRAWN')">撤回求购</button></div></article></div>
