late #footer><el-button :disabled="uploading" @click="publishVisible=false">取消</el-button><el-button type="primary" :loading="saving||uploading" :disabled="uploading" @click="saveGoods">{{editing?'保存修改':'发布商品'}}</el-button></template></el-dialog>
    <el-dialog v-model="wantedVisible" :title="wantForm.id?'编辑求购信息':'发布一条求购'" width="540px"><p class="dialog-tip">编辑或发布后会进入管理员审核，通过后同学们就能看见。</p><el-form :model="wantForm" label-position="top"><el-form-item label="想要什么"><el-input v-model="wantForm.title" maxlength="120" placeholder="例如：求购线性代数教材"/></el-form-item><div class="form-columns"><el-form-item label="分类"><el-select v-model="wantForm.category"><el-option v-for="item in categories.slice(1)" :key="item" :label="item" :value="item"/></el-select></el-form-item><el-form-item label="预算（元，0 表示面议）"><el-input-number v-model="wantForm.budget" :min="0" :max="99999999.99" :precision="2"/></el-form-item></div><el-form-item label="具体要求"><el-input v-model="wantForm.description" type="textarea" :rows="4" maxlength="500" show-word-limit placeholder="描述版本、成色和期望交易地点"/></el-form-item></el-form><template #footer><el-button @click="wantedVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="submitWant">提交审核</el-button></template></el-dialog>
    <el-dialog v-model="detailVisible" title="商品详情" width="780px"><div v-if="selected" class="detail"><ProductImage :src="selected.imageUrl" :alt="selected.title"/><div><p class="card-category">{{selected.category}} · {{selected.conditionLevel}}</p><h2>{{selected.title}}</h2><strong class="detail-price">¥{{money(selected.price)}}</strong><p>{{selected.description}}</p><div class="detail-meta"><span><el-icon><Location/></el-icon>{{selected.location}}</span><span><el-icon><User/></el-icon>{{selected.sellerName}}</span><el-tag :type="tagType(selected.status)">{{statusText(selected.status)}}</el-tag></div></div></div><template #footer><div class="detail-actions"><el-button v-if="selected&&!isAdmin" :disabled="saving" @click="toggleFavorite(selected)">{{selected.favorite?'取消收藏':'收藏商品'}}</el-button><el-button @click="openMessages()">留言咨询</el-button><el-button v-if="selected&&!isOwnGoods&&!isAdmin" @click="openReport">举报商品</el-button><el-button v-if="!isAdmin" type="primary" :loading="saving" :disabled="isOwnGoods||!selected?.ownershipVerified||selected?.status!=='ON_SALE'" @click="createOrder">{{isOwnGoods?'我的商品':selected?.status==='ON_SALE'?'我想要':'暂不可购买'}}</el-button></div></template></el-dialog>
    <el-dialog v-model="messageVisible" title="商品咨询" width="660px"><p class="dialog-tip">{{selected?.title}} · {{isOwnGoods?'你可以回复同学们的咨询':'聊清商品细节，再约时间面交'}}</p><div class="message-list" :aria-busy="messageLoading"><p v-if="!messages.length&&!messageLoading" class="empty">还没有留言，发起第一条咨询吧。</p><article v-for="message in messages" :key="message.id" class="message-item"><div class="inbox-head"><span class="mini-avatar">{{message.userName?.slice(0,1)}}</span><strong>{{message.userName}}</strong><small>{{formatDate(message.createdAt)}}</small></div><p>{{message.content}}</p><div v-if="message.replyContent" class="message-reply"><b>{{message.replyName}} 回复</b><p>{{message.replyContent}}</p></div><button v-if="isOwnGoods" class="text-action" @click="openReply(message)">{{message.replyContent?'修改回复':'回复同学'}}</button></article></div><el-pagination v-model:current-page="messagePage" v-model:page-size="messageSize" :page-sizes="[5,10,20]" :disabled="messageLoading" :total="messagesTotal" layout="total, sizes, prev, pager, next" background class="message-pagination"/><el-input v-if="!isAdmin" v-model="messageText" maxlength="500" show-word-limit type="textarea" :rows="3" placeholder="询问成色、配件或交易地点…"/><template #footer><el-button @click="messageVisible=false">关闭</el-button><el-button v-if="!isAdmin" type="primary" :loading="saving" @click="submitMessage">发送留言</el-button></template></el-dialog>
    <el-dialog v-model="replyVisible" title="回复商品咨询" width="480px"><p class="dialog-tip">{{replyTarget?.content}}</p><el-input v-model="replyText" maxlength="500" show-word-limit type="textarea" :rows="4" placeholder="回复同学的问题…"/><template #footer><el-button @click="replyVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="submitReply">发送回复</el-button></template></el-dialog>
    <el-dialog v-model="reportVisible" title="举报商品" width="460px"><p class="dialog-tip">请说明具体问题，管理员会核实商品信息。</p><el-input v-model="reportReason" type="textarea" :rows="4" maxlength="500" show-word-limit placeholder="例如：描述不实、违规商品或交易异常"/><template #footer><el-button @click="reportVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="submitReport">提交举报</el-button></template></el-dialog>
    <el-dialog v-model="notificationsVisible" title="站内通知" width="580px"><p v-if="notificationError" role="alert" class="upload-error">{{notificationError}} <el-button @click="loadNotifications">重试</el-button></p><div :aria-busy="notificationLoading"><p v-if="!notificationLoading&&!notificationError&&!notifications.length">还没有通知</p><article v-for="notice in notifications" :key="notice.id" class="message-item"><strong>{{notice.title}}</strong><p>{{notice.body}}</p><small>{{formatDate(notice.occurredAt)}}</small><el-button v-if="!notice.isRead" :disabled="notificationLoading" @click="readNotification(notice)">标为已读</el-button><span v-else>已读</span></article></div><el-pagination v-model:current-page="noticePage" :page-size="9" :total="noticeTotal" :disabled="notificationLoading" layout="prev, pager, next"/></el-dialog>
    <el-dialog v-model="profileVisible" :title="isAdmin?'管理员账号':'我的账号'" width="420px"><div class="profile-panel"><div class="profile-large">{{currentUser?.nickname?.slice(0,1)}}</div><h3>{{currentUser?.nickname}}</h3><p>{{currentUser?.username}} · {{isAdmin?'管理员':'校园用户'}}</p><button class="button primary" @click="profileVisible=false;go(isAdmin?'admin':'mine')">{{isAdmin?'进入管理后台':'管理我的发布'}}</button><el-form label-position="top" @submit.prevent="saveProfile"><el-form-item label="昵称"><el-input v-model="profileNickname" maxlength="40"/></el-form-item><el-button :loading="saving" @click="saveProfile">保存昵称</el-button><el-form-item label="原密码"><el-input v-model="oldPassword" type="password" autocomplete="current-password"/></el-form-item><el-form-item label="新密码（至少6位）"><el-input v-model="newPassword" type="password" autocomplete="new-password"/></el-form-item><p v-if="profileError" role="alert" class="upload-error">{{profileError}}</p><el-button :loading="saving" @click="savePassword">修改密码</el-button></el-form><button class="button secondary" @click="logout">退出登录</button></div></el-dialog>
    <el-dialog v-model="authVisible" :title="authMode==='login'?'欢迎回到拾光集市':'加入校园好物循环'" width="430px" :close-on-click-modal="false" :show-close="!authLoading" :close-on-press-escape="!authLoading"><div class="auth-panel"><div class="auth-logo">拾</div><p class="auth-subtitle">同校好物，从这里遇见</p><el-form ref="authFormElement" :model="authForm" label-position="top" @submit.prevent="submitAuth"><el-form-item v-if="authMode==='register'" label="昵称"><el-input v-model="authForm.nickname" name="nickname" maxlength="40" placeholder="同学们如何称呼你"/></el-form-item><el-form-item label="用户名"><el-input v-model="authForm.username" name="username" maxlength="40" placeholder="输入用户名" autocomplete="username"/></el-form-item><el-form-item label="密码"><el-input v-model="authForm.password" name="password" type="password" show-password placeholder="输入密码" :autocomplete="authMode==='login'?'current-password':'new-password'" @keyup.enter="submitAuth"/></el-form-item><p v-if="authError" tabindex="-1" role="alert" class="upload-error">{{authError}}</p><el-button class="auth-submit" type="primary" :loading="authLoading" @click="submitAuth">{{authMode==='login'?'登录集市':'注册并登录'}}</el-button><el-button class="auth-cancel" :disabled="authLoading" @click="authVisible=false">取消，先逛逛</el-button></el-form><button class="auth-switch" @click="authMode=authMode==='login'?'register':'login'">{{authMode==='login'?'还没有账号？立即注册':'已有账号？返回登录'}}</button></div></el-dialog>
  </div>
</template>

<script setup>
import {computed, reactive, ref, onMounted, onUnmounted, watch} from 'vue'
import {api} from './api.js'
import {ElMessage, ElMessageBox} from 'element-plus'
import {ArrowDown, ArrowRight, Bell, ChatDotRound, Close, Edit, Filter, Goods, Loading, Location, Plus, Refresh, Search, Shop, Star, StarFilled, Tickets, Top, UploadFilled, User} from '@element-plus/icons-vue'
import AdminConsole from './AdminConsole.vue'
import PageBanner from './PageBanner.vue'
import ProductImage from './ProductImage.vue'

const categories=['全部','教材书籍','数码产品','生活用品','运动户外'], conditions=['全新','九成新','八成新','七成新']
const goodsStatuses=['ON_SALE','OFF_SHELF','RESERVED','SOLD'], wantStatuses=['PENDING','PUBLISHED','HIDDEN','FOUND','WITHDRAWN']
const currentUser=ref(null)
const isAdmin=computed(()=>currentUser.value?.role==='ADMIN')
const navItems=computed(()=>isAdmin.value?[{key:'admin',label:'管理后台',icon:Shop},{key:'market',label:'浏览集市',icon:Search}]:[{key:'market',label:'发现好物',icon:Shop},{key:'wanted',label:'求购大厅',icon:Search},{key:'mine',label:'我的发布',icon:Goods},{key:'favorites',label:'收藏',icon:Star},{key:'orders',label:'订单',icon:Tickets},{key:'messages',label:'消息',icon:ChatDotRound}])
const view=ref(isAdmin.value?'admin':'market'), category=ref('全部'), keyword=ref(''), searchTerm=ref(''), items=ref([])
const loading=ref(false), saving=ref(false), pageNumber=ref(1), pageSize=ref(9), pageTotal=ref(0), sortBy=ref('latest'), conditionFilter=ref(''), minPrice=ref(''), maxPrice=ref(''), statusFilter=ref(''), onlyMine=ref(false)
const publishVisible=ref(false), editing=ref(false), detailVisible=ref(false), selected=ref(null), profileVisible=ref(false), reportVisible=ref(false), reportReason=ref('')
const messageVisible=ref(false), messages=ref([]), messagesTotal=ref(0), messagePage=ref(1), messageSize=ref(5), messageLoading=ref(false), messageText=ref(''), replyVisible=ref(false), replyTarget=ref(null), replyText=ref('')
const wantedVisible=ref(false), wantForm=reactive({id:null,title:'',category:'教材书籍',budget:0,description:''})
const authVisible=ref(false), authLoading=ref(false), authMode=ref('login'), authForm=reactive({username:'',password:'',nickname:''}), authFormElement=ref(null), authError=ref('')
const form=reactive({id:null,title:'',price:1,category:'教材书籍',conditionLevel:'九成新',location:'校本部',description:'',imageUrl:''})
const imageInput=ref(null), uploading=ref(false), uploadError=ref(''), uploadProgress=ref(0)
const pageTitle=computed(()=>({market:'发现校园里的好物',wanted:'你想要的，也许同学正好有',mine:'我的闲置小铺',favorites:'把喜欢的好物留在这里',orders:'每一次好物交接',messages:'和同学聊聊好物'}[view.value]))
const pageEyebrow=computed(()=>({market:'EXPLORE THE CAMPUS',wanted:'WANTED BOARD',mine:'MY LITTLE SHOP',favorites:'SAVED FOR LATER',orders:'MY ORDERS',messages:'CAMPUS MESSAGES'}[view.value]))
const pageDescription=computed(()=>({market:'同校好物，新一轮的使用从你开始。',wanted:'发布你的需求，让同校闲置和你双向遇见。',mine:'编辑商品、管理上下架，给闲置一个新去处。',favorites:'心动的商品，等你慢慢挑。',orders:'在这里查看购买意向与交易状态。',messages:'查看你的咨询、卖家的回复，以及待你回复的留言。'}[view.value]))
const emptyText=computed(()=>({market:'换个关键词或分类试试。',wanted:'发布一条求购，让同学知道你在找什么。',mine:'发布第一件好物，开启你的校园小铺。',favorites:'浏览集市，收藏让你心动的商品。',orders:'遇见喜欢的好物后，点击“我想要”。',messages:'收到咨询或回复后，会出现在这里。'}[view.value]))
const isOwnGoods=computed(()=>!!currentUser.value&&selected.value?.sellerId===currentUser.value.id)
const pendingMessages=ref(0)
const invalidPriceRange=computed(()=>minPrice.value!==''&&maxPrice.value!==''&&Number(maxPrice.value)<Number(minPrice.value))
const filteredItems=computed(()=>items.value)
const pagedItems=computed(()=>items.value)
watch([view,pageNumber,pageSize,category,searchTerm,sortBy,conditionFilter,minPrice,maxPrice,statusFilter,onlyMine],(next,previous)=>{if(next.some((value,index)=>index!==1&&value!==previous[index])&&pageNumber.value!==1){pageNumber.value=1;return}loadView()})
watch([messagePage,messageSize],(next,previous)=>{if(next[1]!==previous[1]&&messagePage.value!==1){messagePage.value=1;return}if(messageVisible.value)loadMessages()})
async function request(promise){try{return (await promise).data.data}catch(error){ElMessage.error(error.response?.data?.message||error.response?.data?.detail||'操作失败，请稍后重试');throw error}}
async function run(action){if(saving.value)return;saving.value=true;try{await action()}catch(error){if(error!=='cancel'&&error!=='close'&&!error?.isApiError)ElMessage.error('操作未完成，请刷新后重试')}finally{saving.value=false}}
function requireLogin(){if(currentUser.value)return true;authVisible.value=true;return false}
let listRequest=0
async function loadView(){
  const requestId=++listRequest, activeView=view.value
  if(activeView==='admin'){loading.value=false;return}
  if(invalidPriceRange.value){items.value=[];pageTotal.value=0;loading.value=false;return}
  loading.value=true
  try{
    const urls={market:'/api/goods',mine:'/api/goods/mine',favorites:'/api/goods/favorites',orders:'/api/orders/mine',wanted:'/api/wants',messages:'/api/messages/mine'}
    const params={page:pageNumber.value,size:pageSize.value,keyword:searchTerm.value,category:category.value==='全部'?'':category.value,status:statusFilter.value,condition:conditionFilter.value,minPrice:minPrice.value===''?undefined:minPrice.value,maxPrice:maxPrice.value===''?undefined:maxPrice.value,sort:sortBy.value,onlyMine:onlyMine.value}
    const data=await request(api.get(urls[activeView],{params}))
    if(requestId!==listRequest||activeView!==view.value)return
    pageTotal.value=data.total
    const lastPage=Math.max(1,Math.ceil(data.total/pageSize.value))
    if(pageNumber.value>lastPage){pageNumber.value=lastPage;return}
    items.value=data.records
  }catch{if(requestId===listRequest){items.value=[];pageTotal.value=0}}finally{if(requestId===listRequest)loading.value=false}
}
async function refreshMessages(){if(!currentUser.value||isAdmin.value)return;try{const data=await request(api.get('/api/messages/mine',{params:{page:1,size:1,status:'PENDING',onlyMine:true}}));pendingMessages.value=data.total}catch{}}
function resetFilters(){category.value='全部';keyword.value='';searchTerm.value='';sortBy.value='latest';conditionFilter.value='';minPrice.value='';maxPrice.value='';statusFilter.value='';onlyMine.value=false;pageNumber.value=1}
function applySearch(){const same=searchTerm.value===keyword.value.trim();searchTerm.value=keyword.value.trim();pageNumber.value=1;if(same)loadView()}
function go(key){if(!currentUser.value&&!['market','wanted'].includes(key)){authVisible.value=true;return}if(key==='admin'&&!isAdmin.value)return;const same=view.value===key;view.value=key;resetFilters();items.value=[];pageTotal.value=0;if(same)loadView();scrollTop()}
function openPublish(item=null){if(uploading.value||saving.value||!requireLogin()||isAdmin.value)return;editing.value=!!item;uploadError.value='';Object.assign(form,item?{...item}:{id:null,title:'',price:1,category:'教材书籍',conditionLevel:'九成新',location:'校本部',description:'',imageUrl:''});publishVisible.value=true}
async function chooseImage(event){if(uploading.value)return;const file=event.target.files?.[0];event.target.value='';uploadError.value='';if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type))return uploadError.value='仅支持 JPG、PNG、WEBP 图片';if(file.size>5*1024*1024)return uploadError.value='图片不能超过 5MB';uploading.value=true;uploadProgress.value=0;try{const body=new FormData();let upload=file;if(file.type==='image/webp'){const bitmap=await createImageBitmap(file);try{if(bitmap.width*bitmap.height>20000000)throw new Error('图片超过2000万像素');const canvas=document.createElement('canvas');canvas.width=bitmap.width;canvas.height=bitmap.height;canvas.getContext('2d').drawImage(bitmap,0,0);upload=await new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(new File([blob],'converted.png',{type:'image/png'})):reject(new Error('图片转换失败')),'image/png'));}finally{bitmap.close()}}if(upload.size>5*1024*1024)throw new Error('转换后的图片超过5MB');body.append('file',upload);const data=await request(api.post('/api/uploads/image',body));form.imageUrl=data.url;ElMessage.success('图片上传成功')}catch(error){uploadError.value=error.response?.data?.message||error.message||'图片上传失败，请重试'}finally{uploading.value=false}}
function clearImage(){form.imageUrl='';uploadError.value=''}
function saveGoods(){if(uploading.value)return ElMessage.warning('请等待图片上传完成');if(!form.title.trim()||!form.description.trim()||!form.location.trim())return ElMessage.warning('请填写名称、描述和交易地点');if(form.imageUrl&&!/^(https?:\/\/|\/images\/|\/uploads\/)/.test(form.imageUrl))return ElMessage.warning('图片地址无效');return run(async()=>{const data={...form,title:form.title.trim(),description:form.description.trim()};if(editing.value)await request(api.put('/api/goods/'+form.id,data));else await request(api.post('/api/goods',data));publishVisible.value=false;ElMessage.success(editing.value?'商品已更新':'商品发布成功');await loadView()})}
function toggleFavorite(item){if(!requireLogin())return;return run(async()=>{const data=await request(item.favorite?api.delete('/api/goods/'+item.id+'/favorite'):api.put('/api/goods/'+item.id+'/favorite'));Object.assign(item,data);if(view.value==='favorites'&&!data.favorite)await loadView();ElMessage.success(data.favorite?'已加入收藏':'已取消收藏')})}
function changeStatus(item){return run(async()=>{const value=item.status==='ON_SALE'?'OFF_SHELF':'ON_SALE';const data=await request(api.patch('/api/goods/'+item.id+'/status',null,{params:{value}}));Object.assign(item,data);await loadView();ElMessage.success(value==='ON_SALE'?'商品已上架':'商品已下架')})}
function showDetail(item){selected.value=item;detailVisible.value=true}
let messageRequest=0
async function loadMessages(){
  if(!selected.value)return
  const requestId=++messageRequest,goodsId=selected.value.id
  messageLoading.value=true
  try{const data=await request(api.get('/api/messages/goods/'+goodsId,{params:{page:messagePage.value,size:messageSize.value}}));if(requestId!==messageRequest)return;messagesTotal.value=data.total;const lastPage=Math.max(1,Math.ceil(data.total/messageSize.value));if(messagePage.value>lastPage){messagePage.value=lastPage;return}messages.value=data.records}catch{if(requestId===messageRequest){messages.value=[];messagesTotal.value=0}}finally{if(requestId===messageRequest)messageLoading.value=false}
}
function openMessages(){if(!requireLogin())return;messageText.value='';messages.value=[];messagesTotal.value=0;messagePage.value=1;detailVisible.value=false;messageVisible.value=true;loadMessages()}
function submitMessage(){if(!messageText.value.trim())return ElMessage.warning('请填写留言内容');return run(async()=>{await request(api.post('/api/messages',{goodsId:selected.value.id,content:messageText.value.trim()}));messageText.value='';messagePage.value=1;await loadMessages();await refreshMessages();ElMessage.success('留言已发送')})}
function openReply(message){replyTarget.value=message;replyText.value=message.replyContent||'';replyVisible.value=true}
function submitReply(){if(!replyText.value.trim())return ElMessage.warning('请填写回复内容');return run(async()=>{await request(api.patch('/api/messages/'+replyTarget.value.id+'/reply',{content:replyText.value.trim()}));replyVisible.value=false;if(messageVisible.value)await loadMessages();if(view.value==='messages')await loadView();await refreshMessages();ElMessage.success('回复已发送')})}
async function openMessageGoods(message){try{selected.value=await request(api.get('/api/goods/'+message.goodsId));openMessages()}catch{}}
function openWant(want=null){if(!requireLogin()||isAdmin.value)return;Object.assign(wantForm,want?{id:want.id,title:want.title,category:want.category,budget:Number(want.budget),description:want.description}:{id:null,title:'',category:'教材书籍',budget:0,description:''});wantedVisible.value=true}
function submitWant(){if(!wantForm.title.trim()||!wantForm.description.trim())return ElMessage.warning('请填写求购标题和具体要求');return run(async()=>{const data={...wantForm,title:wantForm.title.trim(),description:wantForm.description.trim()};await request(wantForm.id?api.put('/api/wants/'+wantForm.id,data):api.post('/api/wants',data));wantedVisible.value=false;ElMessage.success('求购已提交，等待审核');go('wanted')})}
function changeWantStatus(want,value){return run(async()=>{await ElMessageBox.confirm(value==='FOUND'?'确认已经找到需要的物品吗？':'确认撤回这条求购吗？','管理求购',{confirmButtonText:'确认',cancelButtonText:'取消'});const data=await request(api.patch('/api/wants/'+want.id+'/status',null,{params:{value}}));Object.assign(want,data);await loadView();ElMessage.success(value==='FOUND'?'已标记为找到':'求购已撤回')})}
function openReport(){if(!requireLogin())return;reportReason.value='';detailVisible.value=false;reportVisible.value=true}
function submitReport(){if(!reportReason.value.trim())return ElMessage.warning('请填写举报原因');return run(async()=>{await request(api.post('/api/reports',{targetType:'GOODS',targetId:selected.value.id,reason:reportReason.value.trim()}));reportVisible.value=false;ElMessage.success('举报已提交')})}
function createOrder(){if(!requireLogin())return;return run(async()=>{await ElMessageBox.confirm('向卖家发送购买意向，并预约这件商品？','确认购买意向',{confirmButtonText:'发送意向',cancelButtonText:'再看看'});const gid=selected.value.id,keyName='campus-intent-'+gid,requestKey=sessionStorage.getItem(keyName)||crypto.randomUUID();sessionStorage.setItem(keyName,requestKey);try{await request(api.post('/api/orders',null,{params:{goodsId:gid,requestKey}}));sessionStorage.removeItem(keyName)}catch(error){if(error.response?.status===409){await loadView();try{selected.value=(await api.get('/api/goods/'+gid)).data.data}catch{}}throw error};detailVisible.value=false;ElMessage.success('购买意向已发送');go('orders')})}
function cancelOrder(order){return run(async()=>{await ElMessageBox.confirm('取消后商品会恢复在售，确认继续吗？','取消购买意向',{confirmButtonText:'确认取消',cancelButtonText:'保留订单'});await request(api.patch('/api/orders/'+order.id+'/cancel'));ElMessage.success('购买意向已取消');await loadView()})}
async function submitAuth(){
  if(authLoading.value)return
  authError.value=''
  const fields=new FormData(authFormElement.value.$el)
  authForm.username=String(fields.get('username')||'').trim()
  authForm.password=String(fields.get('password')||'')
  if(authMode.value==='register')authForm.nickname=String(fields.get('nickname')||'').trim()
  if(!authForm.username||!authForm.password){authError.value='请填写用户名和密码';return}
  authLoading.value=true
  try{
    const response=await api.post(authMode.value==='login'?'/api/auth/login':'/api/auth/register',{...authForm},{timeout:15000})
    const user=response.data.data
    if(!user?.id||!['USER','ADMIN'].includes(user.role))throw new Error('登录响应异常，请重试')
    localStorage.setItem('campus-user',JSON.stringify(user))
    currentUser.value=user;authVisible.value=false;go(user.role==='ADMIN'?'admin':'market')
    refreshMessages();loadNotifications();ElMessage.success(user.role==='ADMIN'?'管理员登录成功':'欢迎来到拾光集市')
  }catch(error){
    const status=error.response?.status
    authError.value=status===401?'用户名或密码错误，或账号已被禁用':status>=500?'登录服务异常，请稍后重试':status===400?'登录信息不完整或格式不正确':error.response?.data?.message||(!error.response&&error.isApiError?'无法连接登录服务，请稍后重试':error.message||'登录失败，请重试')
  }finally{authLoading.value=false}
}
watch(authMode,()=>{authError.value=''})
function clearSession(){currentUser.value=null;localStorage.removeItem('campus-user');profileVisible.value=false;pendingMessages.value=0;noticeRequest++;notifications.value=[];unreadNotifications.value=0;notificationsVisible.value=false;detailVisible.value=false;messageVisible.value=false;view.value='market';resetFilters();loadView();authVisible.value=true}
async function logout(){try{await request(api.post('/api/auth/logout'));clearSession()}catch{}}
function advanceOrder(order,action){return run(async()=>{await ElMessageBox.confirm(action==='complete'?'确认已线下交接完成？本系统不处理资金。':'确认接受这条购买意向？','购买意向',{confirmButtonText:'确认',cancelButtonText:'取消'});await request(api.patch('/api/orders/'+order.id+'/'+action));await loadView();ElMessage.success('意向状态已更新')})}
function scrollToGoods(){document.querySelector('#goods')?.scrollIntoView({behavior:'smooth',block:'start'})}
function scrollTop(){window.scrollTo({top:0,behavior:'smooth'})}
function money(value){return Number(value||0).toFixed(2)}
function formatDate(value){return value?new Date(value).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):''}
function statusText(value){return {ON_SALE:'在售',OFF_SHELF:'已下架',RESERVED:'已预留',SOLD:'已售出',PENDING:view.value==='wanted'?'待审核':'待确认',CONFIRMED:'卖家已确认',COMPLETED:'已完成',CANCELLED:'已取消',PUBLISHED:'求购中',HIDDEN:'未通过审核',FOUND:'已找到',WITHDRAWN:'已撤回',REPLIED:'已回复'}[value]||value}
function tagType(value){return ['ON_SALE','COMPLETED','PUBLISHED','FOUND','REPLIED'].includes(value)?'success':['PENDING','RESERVED'].includes(value)?'warning':'info'}
function bannerAction(target){if(isAdmin.value){go('admin');return}if(target==='publish'){openPublish();return}if(target==='want'){openWant();return}if(target===view.value){scrollToGoods();return}go(target)}
const notificationsVisible=ref(false),notifications=ref([]),notificationError=ref(''),notificationLoading=ref(false),unreadNotifications=ref(0),noticePage=ref(1),noticeTotal=ref(0)
let noticeRequest=0
async function loadNotifications(){if(!currentUser.value)return;const id=++noticeRequest;notificationLoading.value=true;notificationError.value='';try{const data=(await api.get('/api/notifications',{params:{page:noticePage.value,size:9}})).data.data;if(id!==noticeRequest)return;notifications.value=data.records;noticeTotal.value=data.total;unreadNotifications.value=data.unread}catch(error){if(id===noticeRequest)notificationError.value=error.message}finally{if(id===noticeRequest)notificationLoading.value=false}}
function openNotifications(){if(!requireLogin())return;notificationsVisible.value=true;loadNotifications()}
async function readNotification(notice){try{await api.put('/api/notifications/'+notice.id+'/read');await loadNotifications()}catch(error){notificationError.value=error.message}}
watch(noticePage,loadNotifications)
const profileNickname=ref(''),oldPassword=ref(''),newPassword=ref(''),profileError=ref('')
watch(profileVisible,value=>{if(value){profileNickname.value=currentUser.value?.nickname||'';oldPassword.value='';newPassword.value='';profileError.value=''}})
async function saveProfile(){profileError.value='';if(!profileNickname.value.trim())return profileError.value='请填写昵称';return run(async()=>{try{const user=(await api.put('/api/auth/profile',{nickname:profileNickname.value.trim()})).data.data;currentUser.value=user;localStorage.setItem('campus-user',JSON.stringify(user));ElMessage.success('昵称已更新')}catch(error){profileError.value=error.message}})}
async function savePassword(){profileError.value='';if(!oldPassword.value||newPassword.value.length<6)return profileError.value='请填写原密码，新密码至少6位';return run(async()=>{try{await api.put('/api/auth/password',{oldPassword:oldPassword.value,newPassword:newPassword.value});clearSession();ElMessage.success('密码已更新，请重新登录')}catch(error){profileError.value=error.message}})}
function expired(){noticeRequest++;notifications.value=[];unreadNotifications.value=0;clearSession()}
onMounted(async()=>{window.addEventListener('session-expired',expired);try{currentUser.value=(await api.get('/api/auth/me')).data.data;localStorage.setItem('campus-user',JSON.stringify(currentUser.value));view.value=isAdmin.value?'admin':'market';loadNotifications()}catch(error){localStorage.removeItem('campus-user');if(error.response?.status!==401)ElMessage.error(error.message);authVisible.value=true}await loadView();refreshMessages()})
onUnmounted(()=>{window.removeEventListener('session-expired',expired);listRequest++;messageRequest++;noticeRequest++})
</script>
